#!/usr/bin/env python3
"""
Script to fill HWPX template with data from JSON files.
Uses standard library xml.etree.ElementTree instead of lxml.
"""

import json
import re
import zipfile
import os
from io import BytesIO
import xml.etree.ElementTree as ET

# File paths
TEMPLATE_PATH = '/root/safety_audit_template.hwpx'
OUTPUT_PATH = '/root/safety_audit_brief_final.hwpx'
OVERVIEW_JSON = '/root/audit_overview.json'
ACTIONS_JSON = '/root/corrective_actions.json'

# Namespace URI for HWPML
NAMESPACE = 'http://www.hancom.co.kr/hwpml/2010/HWPML'
NSMAP = {'hp': NAMESPACE}

# Risk tier to Korean severity note mapping
RISK_SEVERITY_MAP = {
    'High': '즉시조치',
    'Medium': '계획보완',
    'Low': '모니터링'
}

def load_json_data():
    """Load data from both JSON files."""
    with open(OVERVIEW_JSON, 'r', encoding='utf-8') as f:
        overview = json.load(f)

    with open(ACTIONS_JSON, 'r', encoding='utf-8') as f:
        actions = json.load(f)

    return overview, actions

def build_placeholder_map(overview, actions):
    """Build a mapping of placeholders to values."""
    summary = overview['summary']

    # Map placeholders to values
    placeholder_map = {
        '{{점검ID}}': summary['점검ID'],
        '{{현장명}}': summary['현장명'],
        '{{주관점검자}}': summary['주관점검자'],
        '{{점검일}}': summary['점검일'],
        '{{위험등급}}': summary['위험등급'],
        '{{총평}}': summary['총평'],
        '{{보고대상}}': summary['보고대상'],
    }

    # Add corrective actions (조치1, 조치2, 조치3)
    immediate_actions = actions['immediate_actions']
    for i, action in enumerate(immediate_actions, 1):
        placeholder_map[f'{{{{조치{i}}}}}'] = action

    return placeholder_map, summary['위험등급']

def process_text(text, placeholder_map, risk_tier):
    """Replace placeholders and add severity notes to text."""
    if not text:
        return text

    # Replace placeholders
    for placeholder, value in placeholder_map.items():
        text = text.replace(placeholder, value)

    # Add severity note after risk tier
    severity_note = RISK_SEVERITY_MAP.get(risk_tier, '')
    if severity_note:
        # Replace risk tier with risk tier + severity note
        text = text.replace(risk_tier, f"{risk_tier} {severity_note}")

    return text

def reformat_dates(text):
    """Convert YYYY-MM-DD to YYYY.MM.DD format."""
    if not text:
        return text
    return re.sub(r'(\d{4})-(\d{2})-(\d{2})', r'\1.\2.\3', text)

def find_parent_paragraph(element, root):
    """Find the parent paragraph (hp:p) of an element."""
    # Build parent map
    parent_map = {c: p for p in root.iter() for c in p}

    current = element
    while current in parent_map:
        parent = parent_map[current]
        if parent.tag == f'{{{NAMESPACE}}}p':
            return parent
        current = parent
    return None

def process_element_text(element, placeholder_map, risk_tier, modified_paragraphs, root):
    """Process text and tail of an element, tracking modified paragraphs."""
    # Find parent paragraph for text elements
    parent_p = None
    if element.tag == f'{{{NAMESPACE}}}t':
        parent_p = find_parent_paragraph(element, root)

    # Process text content
    if element.text:
        original_text = element.text
        new_text = process_text(original_text, placeholder_map, risk_tier)
        new_text = reformat_dates(new_text)
        if new_text != original_text:
            element.text = new_text
            if parent_p is not None:
                modified_paragraphs.add(id(parent_p))

    # Process tail content (text after element close tag)
    if element.tail:
        original_tail = element.tail
        new_tail = process_text(original_tail, placeholder_map, risk_tier)
        new_tail = reformat_dates(new_tail)
        if new_tail != original_tail:
            element.tail = new_tail

def remove_linesegarray(paragraph):
    """Remove hp:linesegarray elements from a paragraph."""
    linesegarray_tag = f'{{{NAMESPACE}}}linesegarray'
    for child in list(paragraph):
        if child.tag == linesegarray_tag:
            paragraph.remove(child)

def check_remaining_placeholders(root):
    """Check if any {{...}} placeholders remain in the document."""
    pattern = re.compile(r'\{\{[^}]+\}\}')

    for elem in root.iter():
        if elem.text and pattern.search(elem.text):
            return True, f"Found placeholder in text: {elem.text}"
        if elem.tail and pattern.search(elem.tail):
            return True, f"Found placeholder in tail: {elem.tail}"

    return False, None

def indent_xml(elem, level=0):
    """Add pretty-printing indentation to XML (optional)."""
    i = "\n" + level*"  "
    if len(elem):
        if not elem.text or not elem.text.strip():
            elem.text = i + "  "
        if not elem.tail or not elem.tail.strip():
            elem.tail = i
        for child in elem:
            indent_xml(child, level+1)
        if not elem.tail or not elem.tail.strip():
            elem.tail = i
    else:
        if level and (not elem.tail or not elem.tail.strip()):
            elem.tail = i

def process_section_xml(xml_content, placeholder_map, risk_tier):
    """Process a section XML file, replacing placeholders and cleaning up."""
    # Register namespace
    ET.register_namespace('hp', NAMESPACE)

    # Parse XML
    root = ET.fromstring(xml_content)

    # Track modified paragraphs (using id() as hashable key)
    modified_ids = set()
    id_to_element = {}

    # Build id to element mapping
    for elem in root.iter():
        elem_id = id(elem)
        id_to_element[elem_id] = elem

    # Process all elements with text or tail
    for elem in root.iter():
        # Find parent paragraph for text elements
        parent_p = None
        if elem.tag == f'{{{NAMESPACE}}}t':
            parent_p = find_parent_paragraph(elem, root)

        # Process text content
        if elem.text:
            original_text = elem.text
            new_text = process_text(original_text, placeholder_map, risk_tier)
            new_text = reformat_dates(new_text)
            if new_text != original_text:
                elem.text = new_text
                if parent_p is not None:
                    modified_ids.add(id(parent_p))

        # Process tail content (text after element close tag)
        if elem.tail:
            original_tail = elem.tail
            new_tail = process_text(original_tail, placeholder_map, risk_tier)
            new_tail = reformat_dates(new_tail)
            if new_tail != original_tail:
                elem.tail = new_tail

    # Remove linesegarray from modified paragraphs
    linesegarray_tag = f'{{{NAMESPACE}}}linesegarray'
    for elem_id in modified_ids:
        paragraph = id_to_element.get(elem_id)
        if paragraph is not None:
            for child in list(paragraph):
                if child.tag == linesegarray_tag:
                    paragraph.remove(child)

    # Check for remaining placeholders
    has_placeholders, error_msg = check_remaining_placeholders(root)
    if has_placeholders:
        raise ValueError(f"Remaining placeholders found: {error_msg}")

    # Serialize back to string with XML declaration
    # Use encoding='unicode' and manually add declaration for proper UTF-8 handling
    xml_str = ET.tostring(root, encoding='unicode')
    xml_str = '<?xml version="1.0" encoding="UTF-8"?>\n' + xml_str

    return xml_str.encode('utf-8')

def main():
    """Main function to process the HWPX template."""
    print("Loading JSON data...")
    overview, actions = load_json_data()

    print("Building placeholder map...")
    placeholder_map, risk_tier = build_placeholder_map(overview, actions)

    print(f"Risk tier: {risk_tier}")
    print(f"Placeholders to replace: {list(placeholder_map.keys())}")

    # Create output HWPX file
    print(f"Creating output file: {OUTPUT_PATH}")
    with zipfile.ZipFile(TEMPLATE_PATH, 'r') as zin:
        with zipfile.ZipFile(OUTPUT_PATH, 'w', zipfile.ZIP_DEFLATED) as zout:
            for item in zin.infolist():
                data = zin.read(item.filename)

                # Process section XML files
                if item.filename.startswith('Contents/section') and item.filename.endswith('.xml'):
                    print(f"Processing {item.filename}...")
                    try:
                        data = process_section_xml(data, placeholder_map, risk_tier)
                        print(f"  Successfully processed {item.filename}")
                    except Exception as e:
                        print(f"  Error processing {item.filename}: {e}")
                        raise

                # Write to output
                zout.writestr(item, data)

    print(f"Output file created: {OUTPUT_PATH}")
    print("Done!")

if __name__ == '__main__':
    main()

